import java.util.*;import com.koios.game.arpg.*;import com.koios.game.model.item.*;import com.koios.game.model.player.Player;import com.koios.game.def.ItemDefinition;
public final class CurrencyExpansionCheck {
 static int checks;static void check(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 static int explicit(ItemRoll r){return r.getMap()!=null?Integer.bitCount(r.getMap().mods):(int)r.getAffixes().stream().filter(a->a.getLayer()==ItemRoll.Layer.PREFIX||a.getLayer()==ItemRoll.Layer.SUFFIX).count();}
 static Item gear(ItemRoll.Rarity rarity,int count){Item i=EquipmentBases.create(EquipmentBases.starter(true),20);if(rarity!=ItemRoll.Rarity.NORMAL){for(int seed=0;;seed++){List<ItemRoll.Affix> list=AffixCatalog.roll(i,rarity,new Random(seed));ItemRoll r=i.getRoll().changed(rarity,true,0,list,null);if(explicit(r)==count){i.setRoll(r);break;}}}List<ItemRoll.Affix> all=new ArrayList<>(i.getRoll().getAffixes());all.add(new ItemRoll.Affix("test_enchant",ItemRoll.Layer.ENCHANT,1,new Modifier(Stat.LIFE,Modifier.Operation.FLAT,2)));i.setRoll(i.getRoll().changed(rarity,true,0,all,null));return i;}
 static void preserved(ItemRoll before,ItemRoll after){check(before.getInstanceId().equals(after.getInstanceId()),"Craft UUID preserved");for(ItemRoll.Affix a:before.getAffixes())if(a.getLayer()!=ItemRoll.Layer.PREFIX&&a.getLayer()!=ItemRoll.Layer.SUFFIX)check(after.getAffixes().contains(a),"Every implicit/enchant remains the same object");AffixRules.validateGenerated(after);}
 static ItemRoll op(Item item,String action,int delta,ItemRoll.Rarity rarity){ItemRoll before=item.getRoll(),after=CurrencyCrafting.apply(item,action,new Random(139));check(item.getRoll()==before,"Preparation never mutates input");check(after.getRarity()==rarity&&explicit(after)==explicit(before)+delta,"Exact explicit count/rarity for "+action);preserved(before,after);return after;}
 static void atomic(Player p,Item item,int currency,boolean success){p.getInventory().set(0,item);p.getInventory().set(1,new Item(currency,2));String encoded=ItemRollCodec.encode(item);CraftingCurrency.use(p,1,0);check(p.getInventory().getCount(currency)==(success?1:2),"Currency charged exactly on success "+currency);if(!success)check(encoded.equals(ItemRollCodec.encode(item)),"Failure leaves target unchanged");}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("currencyexpand",78);PrototypeIntegrationCheck.idle(p);
 for(int id:new int[]{22407,22408,22409,22415,22416})check(CraftingCurrency.index(id)>=6&&ItemDefinition.forId(id).isStackable()&&ItemDefinition.forId(id).getName().contains("Orb"),"New currency registered/stackable/named");
 for(int id:CraftingCurrency.IDS)check(ItemTooltip.lines(new Item(id),false).stream().anyMatch(line->line.contains("Right-click Use")),"Every new currency tooltip renders use instructions");
 Item magic=gear(ItemRoll.Rarity.MAGIC,1);ItemRoll aug=op(magic,"augmentation",1,ItemRoll.Rarity.MAGIC);for(ItemRoll.Affix a:magic.getRoll().getAffixes())check(aug.getAffixes().contains(a),"Augmentation retains all existing modifiers");magic.setRoll(aug);atomic(p,magic,22408,false);ItemRoll regal=op(magic,"regal",1,ItemRoll.Rarity.RARE);for(ItemRoll.Affix a:magic.getRoll().getAffixes())check(regal.getAffixes().contains(a),"Regal retains existing modifier rolls");magic.setRoll(regal);op(magic,"scour",-3,ItemRoll.Rarity.NORMAL);op(magic,"annul",-1,ItemRoll.Rarity.RARE);
 Item filled=gear(ItemRoll.Rarity.RARE,6);atomic(p,filled,22402,false);atomic(p,gear(ItemRoll.Rarity.MAGIC,1),22402,false);atomic(p,gear(ItemRoll.Rarity.MAGIC,1),22401,false);atomic(p,gear(ItemRoll.Rarity.MAGIC,1),22400,false);atomic(p,gear(ItemRoll.Rarity.RARE,4),22407,false);atomic(p,gear(ItemRoll.Rarity.NORMAL,0),22415,false);atomic(p,MapRuns.gem(1,false),22407,false);
 for(int id:CraftingCurrency.IDS){Item unid=gear(ItemRoll.Rarity.MAGIC,1);unid.setRoll(unid.getRoll().changed(unid.getRoll().getRarity(),false,0,unid.getRoll().getAffixes(),null));if(id!=22405)atomic(p,unid,id,false);if(id!=22404&&id!=22405){Item corrupt=gear(ItemRoll.Rarity.RARE,4);corrupt.setRoll(corrupt.getRoll().changed(corrupt.getRoll().getRarity(),true,1,corrupt.getRoll().getAffixes(),null));atomic(p,corrupt,id,false);}}
 for(int id:new int[]{22407,22408,22409,22415,22416})atomic(p,gear(ItemRoll.Rarity.MAGIC,1),id,true);
 for(int seed=0;seed<100;seed++){Item i=gear(ItemRoll.Rarity.MAGIC,1);ItemRoll altered=CurrencyCrafting.apply(i,"alteration",new Random(seed));check(altered.getRarity()==ItemRoll.Rarity.MAGIC&&explicit(altered)>=1&&explicit(altered)<=2,"Alteration respects magic budgets");i.setRoll(CurrencyCrafting.apply(i,"regal",new Random(seed)));while(explicit(i.getRoll())<6)i.setRoll(CurrencyCrafting.apply(i,"add",new Random(seed)));check(explicit(i.getRoll())==6,"Exalt fills rare to six without family duplication");while(explicit(i.getRoll())>0)i.setRoll(CurrencyCrafting.apply(i,"annul",new Random(seed)));check(i.getRoll().getRarity()==ItemRoll.Rarity.RARE,"Annul last explicit never downgrades rarity");atomic(p,i,22416,false);}
 for(int mods=1;mods<=3;mods++){Item map=MapRuns.map(3,mods);map.setRoll(map.getRoll().changed(ItemRoll.Rarity.MAGIC,true,0,map.getRoll().getAffixes(),map.getRoll().getMap()));if(Integer.bitCount(mods)==1)op(map,"augmentation",1,ItemRoll.Rarity.MAGIC);else atomic(p,map,22408,false);ItemRoll promoted=op(map,"regal",1,ItemRoll.Rarity.RARE);check((promoted.getMap().mods&mods)==mods,"Regal map retains old modifier bits");map.setRoll(promoted);op(map,"annul",-1,ItemRoll.Rarity.RARE);op(map,"scour",-explicit(map.getRoll()),ItemRoll.Rarity.NORMAL);}
 for(int id:new int[]{22407,22408,22409,22415,22416}){Item map=MapRuns.map(3,1);atomic(p,map,id,true);}atomic(p,MapRuns.map(3,1),22401,false);atomic(p,MapRuns.map(3,1),22402,false);atomic(p,MapRuns.map(3,1),22400,false);atomic(p,MapRuns.map(3,7),22401,true);
 Item zeroMagic=gear(ItemRoll.Rarity.MAGIC,1);zeroMagic.setRoll(CurrencyCrafting.apply(zeroMagic,"annul",new Random(1)));check(zeroMagic.getRoll().getRarity()==ItemRoll.Rarity.MAGIC&&explicit(zeroMagic.getRoll())==0,"Annul last magic explicit retains magic rarity");atomic(p,zeroMagic,22416,false);
 Item fullMap=MapRuns.map(3,7);atomic(p,fullMap,22402,false);for(int n=0;n<CraftingCurrency.LEGACY.length;n++)p.getInventory().set(n,new Item(CraftingCurrency.LEGACY[n],2));CraftingCurrency.exchange(p);for(int n=0;n<CraftingCurrency.LEGACY.length;n++)check(p.getInventory().getCount(CraftingCurrency.LEGACY[n])==0&&p.getInventory().getCount(CraftingCurrency.IDS[n])>=2,"Six-entry legacy migration unaffected by eleven currencies");System.out.println("Passed "+checks+" staged currency expansion checks.");}
}
